// OTHVM — final output normalizer: compact JSON, capped strings, capped total size
const out = [];
let total = 0;
for (const item of $input.all().slice(0, 25)) {
  if (item.error) { const e = item.error; const msg = [e.message, e.description].filter((x) => typeof x === 'string' && x).join(' — ') || 'unknown error'; out.push({ json: { ok: false, error: msg.slice(0, 400) } }); continue; }
  const j = item.json || {};
  if (j.ok === false || (Object.keys(j).length === 1 && 'error' in j)) { const e = j.error; const msg = typeof e === 'string' ? e : (e && typeof e === 'object' ? ([e.message, e.description].filter((x) => typeof x === 'string' && x).join(' — ') || 'unknown error') : String(e || 'unknown error')); out.push({ json: { ok: false, error: msg.slice(0, 400) } }); continue; }
  const o = {};
  for (const [k, v] of Object.entries(j)) {
    if (v === null || v === undefined) continue;
    if (typeof v === 'string') o[k] = v.length > 400 ? v.slice(0, 400) + '\u2026' : v;
    else if (typeof v === 'object') { const s = JSON.stringify(v); o[k] = s.length > 500 ? s.slice(0, 500) + '\u2026' : v; }
    else o[k] = v;
  }
  if (!Object.keys(o).length) continue;
  const s = JSON.stringify(o);
  if (total + s.length > 12000) break;
  total += s.length;
  out.push({ json: o });
}
return out.length ? out : [{ json: { ok: true, note: 'no results' } }];

// OTHVM — Translate: وحّد text (نص واحد أو مصفوفة) لعناصر قابلة للترجمة
const j = $input.first().json || {};
const raw = j.text;
const texts = Array.isArray(raw) ? raw : [raw];
const to = String(j.toLanguage || 'en').trim();
const from = String(j.fromLanguage || 'auto').trim() || 'auto';
return texts.map((t) => ({ json: { text: String(t === undefined || t === null ? '' : t), toLanguage: to, fromLanguage: from } }));

// OTHVM — Translate: parse any known response shape into {ok, translatedText, detectedLanguage}
const items = $input.all();
const first = (items[0] && items[0].json) || {};
let raw;
if (Array.isArray(first)) raw = first;
else if (first && typeof first === 'object' && first.data !== undefined) raw = first.data;
else if (first && typeof first === 'object' && typeof first.translatedText === 'string') return [{ json: { ok: true, translatedText: first.translatedText, detectedLanguage: first.detectedLanguage || '' } }];
else if (items.length > 1) raw = items.map((i) => i.json);
else raw = first;

let text = '';
let detected = '';
if (Array.isArray(raw)) {
  if (raw.length && Array.isArray(raw[0])) {
    if (Array.isArray(raw[0][0])) {
      // legacy: [[["txt","orig",...],...], null, "en", ...]
      text = raw[0].map((s) => String(s[0])).join('');
      detected = typeof raw[2] === 'string' ? raw[2] : '';
    } else {
      // clients5 segments: [["txt","ar"], ...]
      text = raw.map((s) => (Array.isArray(s) ? String(s[0]) : String(s))).join(' ');
      detected = raw[0] && typeof raw[0][1] === 'string' ? raw[0][1] : '';
    }
  } else if (typeof raw[0] === 'string') {
    // single pair: ["txt","ar"]
    text = raw[0];
    detected = typeof raw[1] === 'string' ? raw[1] : '';
  }
}
if (!text) throw new Error('رد غير متوقع من خدمة الترجمة: ' + JSON.stringify(raw).slice(0, 200));
return [{ json: { ok: true, translatedText: text, detectedLanguage: detected } }];

// OTHVM — expand the generic params object into the flat fields the workflow expects.
const j = $json || {};
let p = j.params;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { p = {}; } }
if (!p || typeof p !== 'object' || Array.isArray(p)) p = {};
const out = Object.assign({}, p);
for (const k of ['operation', 'action', 'category']) {
  if (j[k] !== undefined && j[k] !== null && j[k] !== '') out[k] = j[k];
}
return [{ json: out }];
